function example() {
  const [open, setOpen] = React.useState(false);
  const [width, setWidth] = React.useState<number | null>(null);
  const modalRef = React.useRef<HTMLDivElement>(null);

  return (
    <>
      <Button color="info" onClick={() => setOpen(true)}>
        Open and measure
      </Button>
      <Modal
        active={open}
        onClose={() => setOpen(false)}
        ref={modalRef}
        modalCardTitle="Measured through the ref"
      >
        <Button
          onClick={() =>
            setWidth(modalRef.current?.getBoundingClientRect().width ?? null)
          }
        >
          Measure
        </Button>
        <p>Width: {width === null ? '—' : `${Math.round(width)}px`}</p>
      </Modal>
    </>
  );
}

function example() {
  const [open, setOpen] = useState(false);
  const closeModal = () => setOpen(false);

  return (
    <>
      <Button color="success" onClick={() => setOpen(true)}>
        Show Modal
      </Button>
      <Modal isActive={open} onClose={closeModal}>
        <Modal.Background onClick={closeModal} />
        <Modal.Content>
          <Box>
            <Title size="4">Custom Content</Title>
            <Paragraph>Using compound components for full control!</Paragraph>
          </Box>
        </Modal.Content>
        <Modal.Close variant="floating" />
      </Modal>
    </>
  );
}
